            <TextInput
              label="Email"
              type="email"
              size="l"
              placeholder="you@example.com"
              value={email}
              onUpdate={setEmail}
            />

            <PasswordInput
              label="Пароль"
              size="l"
              placeholder="Введите пароль"
              value={password}
              onUpdate={setPassword}
            />

            <Checkbox
              content="Запомнить меня"
              size="l"
              checked={remember}
              onUpdate={setRemember}
            />

            <Button view="action" size="l" width="max" type="submit">
              Войти
            </Button>
          </form>
        </Card>
      </main>
    </ThemeProvider>
  );
}

